def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    seen_edges = set()
    for src, dst in edges:
        if (src, dst) not in seen_edges:
            seen_edges.add((src, dst))
            adj[src].add(dst)
            in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    result = {}
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.fullmatch(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and ((value[0] == "'" and value[-1] == "'")
                                or (value[0] == '"' and value[-1] == '"')):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    lines = text.split('\n')

    events = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    break
                events.append(data)
            data_lines = []
        elif line.startswith(':'):
            continue
        else:
            if ':' in line:
                field, _, value = line.partition(':')
                if value.startswith(' '):
                    value = value[1:]
            else:
                field = line
                value = ''
            if field == 'data':
                data_lines.append(value)

    return events

import math


def retry_delay(attempt, base, cap):
    if isinstance(attempt, bool) or not isinstance(attempt, int):
        raise ValueError("attempt must be a nonnegative integer")
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if not isinstance(base, (int, float)) or not isinstance(cap, (int, float)):
        raise ValueError("base and cap must be finite nonnegative numbers")
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be nonnegative")
    if not math.isfinite(base) or not math.isfinite(cap):
        raise ValueError("base and cap must be finite")

    if base == 0 or cap == 0:
        return 0.0
    if base >= cap:
        return float(cap)

    # 0 < base < cap
    # Use logarithms to decide whether base * 2**attempt >= cap
    # without ever constructing 2**attempt for enormous attempt.
    # log2(base * 2**attempt) == log2(base) + attempt
    if math.log2(base) + attempt >= math.log2(cap):
        return float(cap)

    # Here attempt is necessarily small (bounded by ~2100 for finite floats),
    # so 2**attempt is a perfectly manageable integer.
    return float(min(cap, base * (2 ** attempt)))

def fifo_admit(active, queued, budget, slots):
    for req in queued:
        if req > budget:
            raise ValueError(f"Reservation {req} exceeds the whole budget {budget}")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    idx = 0
    for req in queued:
        if req <= remaining_budget and remaining_slots >= 1:
            admitted.append(req)
            remaining_budget -= req
            remaining_slots -= 1
            idx += 1
        else:
            break

    remaining = list(queued[idx:])
    return (admitted, remaining)
